solution:
def pack_context(chunks, budget):
    if budget <= 0:
        return []
    order = sorted(range(len(chunks)), key=lambda i: (-chunks[i]["score"], i))
    left = budget
    taken = []
    for i in order:
        if chunks[i]["tokens"] <= left:
            taken.append(chunks[i]["id"])
            left -= chunks[i]["tokens"]
    return taken
